#!/usr/bin/env node
// Переводит ботов администраторов с long polling на webhook в проекте tg-channel-manager.
// Запуск:  node add-webhook.mjs [путь/к/проекту]      (по умолчанию — текущая папка)
// Требует уже установленной изоляции администраторов (add-isolation.mjs).
// Всё или ничего: если файл отличается от ожидаемого, скрипт ничего не меняет. Повторный запуск безопасен; копии — *.bak-webhook.
// Новых зависимостей и изменений схемы БД нет.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] || '.');
const dec = (s) => Buffer.from(s, 'base64').toString('utf8');
const p = (f) => path.join(root, f);
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const exists = (f) => fs.existsSync(p(f));
const read = (f) => fs.readFileSync(p(f), 'utf8');

const NEW_FILES = {
 "server/express/routes/telegram.js": "",
 "server/express/routes/bot.js": "",
 "pages/bot.vue": "",
 "scripts/doctor.js": "",
 "docs/SETUP.md": ""
};
const REPLACE = {
 "server/express/bot.js": {
  "content": "",
  "known": [
   "849090b91935da4eefcfd5617dca0ef712e219068ca7d6c9223516cb99b9a991"
  ]
 }
};
const GROUPS = JSON.parse(dec(''));
const SOFT = JSON.parse(dec(''));

const fail = (lines) => {
  console.error('Ничего не изменено:');
  for (const l of lines) console.error('  - ' + l);
  process.exit(1);
};

// 0. зависимости
if (!exists('server/express/bot.js') || !/workspace_bots/.test(read('server/express/bot.js')) || !exists('server/express/routes/bot.js'))
  fail(['изоляция администраторов (отдельные боты) не установлена: сначала  node add-isolation.mjs ' + root]);

// 1. проверяем всё заранее
const conflicts = [];
const plan = { groups: [], replaces: [], soft: [], skipped: [] };
for (const g of GROUPS) {
  if (!exists(g.rel)) { conflicts.push(`${g.rel}: файл не найден`); continue; }
  const text = read(g.rel);
  if (text.includes(g.marker)) continue;
  const missing = g.pairs.filter(([o]) => !text.includes(o)).length;
  if (missing) conflicts.push(`${g.rel}: не найдено ${missing} из ${g.pairs.length} мест для правки (${g.marker})`);
  else plan.groups.push(g);
}
for (const [rel, { content, known }] of Object.entries(REPLACE)) {
  if (!exists(rel)) { conflicts.push(`${rel}: файл не найден`); continue; }
  const now = sha(read(rel));
  if (now === sha(dec(content))) continue;
  if (known.includes(now)) plan.replaces.push({ rel, content: dec(content) });
  else conflicts.push(`${rel}: файл изменён вами и целиком заменяется в этой версии (нужна ручная правка)`);
}
for (const g of SOFT) { // необязательные файлы: конфиги и README
  if (!exists(g.rel)) { plan.skipped.push(`${g.rel}: файла нет`); continue; }
  const text = read(g.rel);
  if (text.includes(g.marker)) continue;
  if (g.pairs.every(([o]) => text.includes(o))) plan.soft.push(g);
  else plan.skipped.push(`${g.rel}: отличается от ожидаемого, добавьте PUBLIC_URL / BOT_MODE вручную (см. docs/SETUP.md)`);
}
if (conflicts.length) {
  conflicts.push('Внесите правки вручную по webhook.patch (все файлы сразу).');
  fail(conflicts);
}

// 2. применяем
const backup = (file) => fs.existsSync(file + '.bak-webhook') || fs.copyFileSync(file, file + '.bak-webhook');
const write = (rel, text, mark) => {
  if (exists(rel)) backup(p(rel));
  fs.mkdirSync(path.dirname(p(rel)), { recursive: true });
  fs.writeFileSync(p(rel), text);
  console.log(`${mark} ${rel}`);
};
const apply = (rel, pairs) => {
  let out = read(rel);
  for (const [o, n] of pairs) out = out.replace(o, () => n);
  return out;
};
let changed = 0;
for (const [rel, b64] of Object.entries(NEW_FILES)) {
  if (exists(rel) && read(rel) === dec(b64)) console.log(`= ${rel}: без изменений`);
  else { write(rel, dec(b64), exists(rel) ? '~' : '+'); changed++; }
}
for (const { rel, content } of plan.replaces) { write(rel, content, '~'); changed++; }
for (const g of plan.groups) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
for (const g of plan.soft) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
if (!changed) console.log('Всё уже применено.');
for (const s of plan.skipped) console.warn('! пропущено: ' + s);

console.log('\nГотово. Дальше:');
console.log('  1) в .env задайте PUBLIC_URL=https://ваш-домен (публичный HTTPS-адрес приложения, без слэша в конце);');
console.log('  2) npm run build && pm2 restart ecosystem.config.cjs --update-env   (или systemctl restart / docker compose up -d --build);');
console.log('  3) при старте webhook зарегистрируется у каждого бота автоматически; статус — на странице «Бот», проверка — npm run doctor.');
console.log('Без PUBLIC_URL боты продолжат работать через polling. В doctor.js и package.json должен быть скрипт "doctor" (npm run doctor).');
